// Generated by vibelang from worker/SessionKeys.ts; the migrate flow writes it again with each batch.
import { WebCryptoCipher } from "@smthrs/control";
import { digestSync } from "@smthrs/crypto";
import { Core } from "@smthrs/integrations";
import { Effect, Option, Redacted } from "effect";
export const MIN_SECRET_LENGTH = 32;
export const LEGACY_KEY = "legacy";
export const digest = (value) => digestSync(value);
